<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Temperature Converter Online','description'=>'Convert Celsius, Fahrenheit and Kelvin values instantly.','url'=>'https://smarttoolz.in/tools/temperature-converter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">TEMPERATURE</span><h1>Temperature Converter</h1><p>Convert Celsius, Fahrenheit and Kelvin values instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Value<input id="v" type="number" step="any" value="0"></label><label>From<select id="a"><option>Celsius</option><option>Fahrenheit</option><option>Kelvin</option></select></label><label>To<select id="b"><option>Fahrenheit</option><option>Celsius</option><option>Kelvin</option></select></label><button id="go" class="tool-btn">Convert</button><p id="o" style="font-size:22px;font-weight:800"></p></div></section></main><script>(()=>{const $=id=>document.getElementById(id),o=$('o');function c(v,a){return a==='Celsius'?v:a==='Fahrenheit'?(v-32)*5/9:v-273.15}$('go').onclick=()=>{let v=+$('v').value,x=c(v,$('a').value),r=$('b').value==='Celsius'?x:$('b').value==='Fahrenheit'?x*9/5+32:x+273.15;o.textContent=`${r.toFixed(4)} ${$('b').value}`};$('go').click()})();</script><?php smarttoolz_tool_page_end(); ?>